add_action( 'woocommerce_product_query', 'perfectpixel_featured_first_flag' );
add_filter( 'posts_clauses', 'perfectpixel_featured_first_clauses', 20, 2 );

function perfectpixel_featured_first_flag( $q ) {
	$orderby = isset( $_GET['orderby'] ) ? wc_clean( wp_unslash( $_GET['orderby'] ) ) : get_option( 'woocommerce_default_catalog_orderby', 'menu_order' );
	if ( 'menu_order' === $orderby ) {
		$q->set( 'perfectpixel_featured_first', 1 );
	}
}

function perfectpixel_featured_first_clauses( $clauses, $query ) {
	global $wpdb;
	if ( ! $query->get( 'perfectpixel_featured_first' ) ) {
		return $clauses;
	}
	$term = get_term_by( 'slug', 'featured', 'product_visibility' );
	if ( ! $term ) {
		return $clauses;
	}
	$clauses['join']   .= $wpdb->prepare( " LEFT JOIN {$wpdb->term_relationships} pp_featured ON ( pp_featured.object_id = {$wpdb->posts}.ID AND pp_featured.term_taxonomy_id = %d )", $term->term_taxonomy_id );
	$clauses['orderby'] = 'pp_featured.object_id IS NULL ASC' . ( $clauses['orderby'] ? ', ' . $clauses['orderby'] : '' );
	return $clauses;
}
